  const storedTheme = localStorage.getItem(THEME_STORAGE_KEY);
  return THEMES.find((theme) => theme === storedTheme) ?? 'light';
}

export function App() {
  const { theme, setTheme } = useTheme();
  const [isDark, setIsDark] = useState(() => readStoredTheme() === 'dark');

